{
  "title": "Hepatitis C Treatment Game",
  "perWatchSecond": 3,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "Adherence threshold",
      "goal": "Show that exceeding the adherence threshold keeps most people susceptible.",
      "control": {
        "parameter": "theta",
        "label": "Treatment adherence proportion",
        "lowEnd": "0.3",
        "highEnd": "0.7"
      },
      "watch": "susceptible fraction at year 200",
      "whatIf": {
        "prompt": "What if adherence is perfect (100 %)?",
        "parameter": "theta",
        "value": 1
      },
      "difference": {
        "compartment": "s",
        "summary": "at",
        "at": 200,
        "time": 200,
        "relation": "higher",
        "by": 0.05
      },
      "effect": "With adherence increased to 100 %, the susceptible fraction at year 200 is about 5 % higher than with the baseline 50 % adherence.",
      "prediction": {
        "prompt": "Predict whether the susceptible fraction will be higher or lower than baseline.",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": {
        "title": "Headline result",
        "quote": "an adherence level exceeding 52% causes the reproduction number to drop below 1, curtailing further spread."
      },
      "carryForward": "Adherence above 52 % keeps the epidemic under control."
    },
    {
      "kind": "result",
      "finding": 4,
      "title": "Quitters drive transmission",
      "goal": "Show that those who quit treatment cause the greatest transmission risk.",
      "control": {
        "parameter": "beta3",
        "label": "Transmission from quitters",
        "lowEnd": "0.025",
        "highEnd": "0.1"
      },
      "watch": "quitters (cq) at year 200",
      "whatIf": {
        "prompt": "What if transmission from quitters doubles to 0.1?",
        "parameter": "beta3",
        "value": 0.1
      },
      "difference": {
        "compartment": "cq",
        "summary": "at",
        "at": 200,
        "time": 200,
        "relation": "higher",
        "by": 0.0135
      },
      "effect": "Doubling β₃ raises the quitters fraction at year 200 by about 0.013, a noticeable rise.",
      "prediction": {
        "prompt": "Will the quitters fraction be higher or lower?",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": {
        "title": "Quitters risk",
        "quote": "$β_{3}$ exerts the strongest influence on the reproduction number."
      },
      "carryForward": "Quitters are key drivers of spread."
    },
    {
      "kind": "result",
      "finding": 6,
      "title": "Boosting treatment recovery",
      "goal": "Demonstrate that increasing recovery on treatment reduces chronic infection.",
      "control": {
        "parameter": "rho",
        "label": "Recovery rate on treatment",
        "lowEnd": "0.053",
        "highEnd": "0.19"
      },
      "watch": "chronically infected on treatment (c) at year 200",
      "whatIf": {
        "prompt": "What if recovery rate rises to 0.19?",
        "parameter": "rho",
        "value": 0.19
      },
      "difference": {
        "compartment": "c",
        "summary": "at",
        "at": 200,
        "time": 200,
        "relation": "lower",
        "by": 0.00005
      },
      "effect": "Increasing ρ to 0.19 cuts the chronic‑on‑treatment fraction at year 200 by about 5 × 10⁻⁵.",
      "prediction": {
        "prompt": "Will the chronic‑on‑treatment fraction be higher or lower?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Recovery rate effect",
        "quote": "When ρ approaches a value of approximately 0.19, we observe that ℛ₀ falls below 1."
      },
      "carryForward": "Higher treatment recovery suppresses the epidemic."
    }
  ],
  "limits": [
    "Adherence above 52 % curtails spread.",
    "Quitters have the strongest transmission impact.",
    "Increasing treatment recovery lowers chronic infection."
  ]
}
